420	    @GET
421	    @NoCache
422	    @Produces(MediaType.APPLICATION_JSON)
423	    @Tag(name = KeycloakOpenAPI.Admin.Tags.REALMS_ADMIN)
424	    @Operation(summary = "Get the top-level representation of the realm It will not include nested information like User and Client representations.")
425	    @APIResponses(value = {
426	        @APIResponse(responseCode = "200", description = "OK", content = @Content(schema = @Schema(implementation = RealmRepresentation.class))),
427	        @APIResponse(responseCode = "403", description = "Forbidden")
428	    })
429	    public RealmRepresentation getRealm() {
430	        if (auth.realm().canViewRealm()) {
431	            return ModelToRepresentation.toRepresentation(session, realm, false);
432	        } else {
433	            auth.realm().requireViewRealmNameList();
434	
435	            RealmRepresentation rep = new RealmRepresentation();
